import{_ as n,C as s,o,c as i,ah as t,E as l}from"./chunks/framework.sPHStHqt.js";const w=JSON.parse('{"title":"Leads","description":"","frontmatter":{},"headers":[],"relativePath":"super-admin/leads.md","filePath":"super-admin/leads.md","lastUpdated":1789630599000}'),r={name:"super-admin/leads.md"};function d(h,e,g,c,p,u){const a=s("ImagePopup");return o(),i("div",null,[e[0]||(e[0]=t('<h1 id="leads" tabindex="-1">Leads <a class="header-anchor" href="#leads" aria-label="Permalink to &quot;Leads&quot;">​</a></h1><p>Every lead, from every tenant, in one list. This is the platform-wide view — a way to see how much selling is happening across your tenants without logging into each CRM.</p><div class="info custom-block"><p class="custom-block-title">What you&#39;ll learn</p><ul><li>How to read the cross-tenant leads list</li><li>What you can edit, and what you can&#39;t</li><li>How to remove a lead</li></ul></div><h2 id="the-leads-list" tabindex="-1">The leads list <a class="header-anchor" href="#the-leads-list" aria-label="Permalink to &quot;The leads list&quot;">​</a></h2><p>Open <strong>Leads</strong> in the sidebar.</p>',5)),l(a,{src:"/images/leads/leads-grid.png",alt:"Cross-tenant leads list"}),e[1]||(e[1]=t('<p>Each row shows:</p><ul><li><strong>ID</strong> — the lead&#39;s number within its own tenant.</li><li><strong>Subject</strong> — the lead&#39;s title.</li><li><strong>Tenant</strong> — which tenant the lead belongs to. This is the column that makes the list platform-wide.</li><li><strong>Stage</strong> — where the lead sits in its pipeline (New, Follow Up, Won, Lost, …).</li><li><strong>Lead Value</strong> — its monetary value.</li><li><strong>Created At</strong> — when it was raised.</li></ul><p>Use <strong>Search</strong> and <strong>Filter</strong> to narrow the list — for example, to everything from one tenant, or everything at the <strong>Won</strong> stage.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The <strong>Converted Leads</strong> and <strong>Conversion Rate</strong> figures on the <a href="/super-admin/dashboard">dashboard</a> are drawn from these same leads — a lead counts as converted once it reaches a <strong>Won</strong> stage.</p></div><h2 id="editing-a-lead" tabindex="-1">Editing a lead <a class="header-anchor" href="#editing-a-lead" aria-label="Permalink to &quot;Editing a lead&quot;">​</a></h2><p>The pencil icon opens a lead. From here you can adjust a few high-level fields:</p><ul><li><strong>Subject</strong></li><li><strong>Lead Value</strong></li><li><strong>Comment</strong></li></ul><p>Everything else — the tenant, the stage, the contact person, the assigned agent — is shown but marked <strong>Read-only details (managed by the tenant)</strong>. That data belongs to the tenant and is changed inside their own CRM, not here.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>This is a light-touch, oversight view. Editing a lead here changes the tenant&#39;s real data. Reserve it for corrections; the day-to-day work happens in the tenant&#39;s own CRM.</p></div><h2 id="deleting-a-lead" tabindex="-1">Deleting a lead <a class="header-anchor" href="#deleting-a-lead" aria-label="Permalink to &quot;Deleting a lead&quot;">​</a></h2><p>The trash icon removes a lead. As with editing, this acts on the tenant&#39;s real data, so use it only to clear out something that genuinely shouldn&#39;t exist.</p><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li>The same platform-wide view for quotes → <a href="/super-admin/quotes">Quotes</a></li><li>The tenants these leads belong to → <a href="/super-admin/tenant-management">Tenant Management</a></li></ul>',13))])}const _=n(r,[["render",d]]);export{w as __pageData,_ as default};
